    private static Integer nearestCadence(int m) {
        int[] presets = {5, 15, 30, 60};
        int best = 30, bestD = Integer.MAX_VALUE;
        for (int p : presets) { int d = Math.abs(p - m); if (d < bestD) { bestD = d; best = p; } }
        return best;
    }

