            steps.setFont(FontManager.getRunescapeSmallFont());
            steps.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            steps.setAlignmentX(Component.LEFT_ALIGNMENT);
            onboardingBanner.add(steps);
