            ok.setFont(FontManager.getRunescapeSmallFont());
            ok.setAlignmentX(Component.LEFT_ALIGNMENT);
            ok.addActionListener(e -> {
                sessionGuideDismissed = true;
                hideSessionGuide();
            });
            onboardingBanner.add(ok);
