package com.gecopilot.client.ui;

import java.text.NumberFormat;

/**
 * Non-blocking check for the GE offer-setup screen.
 *
 * The prices are the ones the plugin already fetched for the overlay quote, not a new request:
 * {@code marketLow} is {@code quote.buy} (what buyers are paying now — hour average low, else latest
 * low) and {@code marketHigh} is {@code quote.sell} (hour average high, else latest high).
 *
 * A sell below that low would fill for less than buyers are paying right now. A buy above that
 * high would pay more than the current market high.
 */
public final class OfferPriceWarning {
    private static final NumberFormat GP = NumberFormat.getIntegerInstance();

    private OfferPriceWarning() {}

    public static final class Warning {
        public final boolean buy;
        public final int offerPrice;
        public final int marketPrice;
        public final int gapGp;
        public final double gapPct;

        Warning(boolean buy, int offerPrice, int marketPrice, int gapGp, double gapPct) {
            this.buy = buy;
            this.offerPrice = offerPrice;
            this.marketPrice = marketPrice;
            this.gapGp = gapGp;
            this.gapPct = gapPct;
        }

        public String headline() {
            return buy ? "Buy over market" : "Sell under buyers";
        }

        /** Gap in gp and percent, plus the market price it is measured against. */
        public String detail() {
            String pct = String.format("%.1f", gapPct);
            String relation = buy ? "over" : "under";
            return GP.format(gapGp) + " gp (" + pct + "%) " + relation + " " + GP.format(marketPrice);
        }
    }

    /**
     * After-tax market margin is too thin to flip. Same skip FlipEngine uses:
     * {@code margin = sell - buy - tax(sell)}, then drop the item when
     * {@code margin <= 0} or {@code margin < minMargin} or {@code marginPct < minRoi}
     * ({@code marginPct = margin * 100 / buy}). Thresholds are the user's flip
     * config (plugin defaults 10 gp and 0.3%), not new numbers.
     *
     * Buy setup only. A sell doesn't choose to enter a thin market.
     */
    public static final class ThinMargin {
        public final long marginGp;
        public final double marginPct;

        ThinMargin(long marginGp, double marginPct) {
            this.marginGp = marginGp;
            this.marginPct = marginPct;
        }

        public String headline() { return "Margin too thin to flip"; }

        /** After-tax margin in gp and percent. */
        public String detail() {
            return GP.format(marginGp) + " gp (" + String.format("%.1f", marginPct) + "%) after tax";
        }
    }

    /** Same rule as {@code com.gecopilot.engine.GeTax}: 2% floored, cap 5M, exempt under 50 gp. */
    static long tax(int price) {
        if (price < 50) return 0;
        return Math.min((long) Math.floor(price * 0.02), 5_000_000L);
    }

    public static ThinMargin evaluateMargin(boolean buy, int marketBuy, int marketSell, long minMargin, double minRoi) {
        if (!buy || marketBuy <= 0 || marketSell <= 0) return null;
        long margin = (long) marketSell - marketBuy - tax(marketSell);
        double marginPct = margin * 100.0 / marketBuy;
        if (margin > 0 && margin >= minMargin && marginPct >= minRoi) return null;
        return new ThinMargin(margin, marginPct);
    }

    public static Warning evaluate(boolean buy, int offerPrice, int marketLow, int marketHigh) {
        if (offerPrice <= 0) return null;
        if (!buy) {
            if (marketLow <= 0 || offerPrice >= marketLow) return null;
            int gap = marketLow - offerPrice;
            return new Warning(false, offerPrice, marketLow, gap, 100.0 * gap / marketLow);
        }
        if (marketHigh <= 0 || offerPrice <= marketHigh) return null;
        int gap = offerPrice - marketHigh;
        return new Warning(true, offerPrice, marketHigh, gap, 100.0 * gap / marketHigh);
    }
}

package com.gecopilot.client.ui;

/**
 * Preview → account prompt (copy A). Hidden on first paint.
 *
 * The preview list is read-only: no watch star and no offer view. The earliest
 * meaningful action is choosing a flip card. That choice reveals the prompt once
 * per session. "Continue without saving" dismisses it for the rest of the session.
 */
public final class PreviewSavePrompt {
    public enum Phase { HIDDEN, ASK, FIELDS, DISMISSED }

    private Phase phase = Phase.HIDDEN;
    private int pickId;

    public Phase phase() { return phase; }

    /** Item the player chose when the prompt opened. 0 if none. */
    public int pickId() { return pickId; }

    /** @return true only on the transition that first reveals the prompt */
    public boolean onFlipChosen(int itemId) {
        if (itemId <= 0 || phase != Phase.HIDDEN) return false;
        pickId = itemId;
        phase = Phase.ASK;
        return true;
    }

    public void saveClicked() {
        if (phase == Phase.ASK) phase = Phase.FIELDS;
    }

    public void continueWithoutSaving() {
        phase = Phase.DISMISSED;
        pickId = 0;
    }

    public void reset() {
        phase = Phase.HIDDEN;
        pickId = 0;
    }
}

package com.gecopilot.client.ui;

import java.util.Locale;

/**
 * First-session next step. Stages only move forward: open the GE, place or view an offer,
 * wait for the fill, then the first live trade. {@code offersKnown} false (GE not opened yet,
 * or an older client that does not report it) stays on the open-GE step unless the server
 * has already recorded an offer or a live trade.
 */
public final class SessionGuide {
    public enum Stage { OPEN_GE, PLACE_OFFER, WAIT_FILL, DONE }

    private SessionGuide() {}

    public static Stage stage(boolean offersKnown, boolean offersSeen, boolean firstLiveTrade) {
        if (firstLiveTrade) return Stage.DONE;
        if (offersSeen) return Stage.WAIT_FILL;
        if (offersKnown) return Stage.PLACE_OFFER;
        return Stage.OPEN_GE;
    }

    /** A failed sync must not walk the session backwards. */
    public static Stage advance(Stage from, Stage to) {
        if (to == null) return from == null ? Stage.OPEN_GE : from;
        if (from == null) return to;
        return to.ordinal() < from.ordinal() ? from : to;
    }

    /** Persistent next action. Null once the guide is finished. */
    public static String banner(Stage stage, String flipName, int placeBuy) {
        if (stage == null || stage == Stage.DONE) return null;
        if (stage == Stage.OPEN_GE) return "Next: open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) {
            if (flipName != null && !flipName.isEmpty() && placeBuy > 0)
                return "Next: in the GE, buy " + flipName + " @ " + String.format(Locale.US, "%,d", placeBuy) + ".";
            return "Next: place or view an offer in the GE.";
        }
        return "Offer synced. Sell it when it fills — see Positions.";
    }

    /** Spoken once when the stage advances. Null on the first observation. */
    public static String transitionToast(Stage from, Stage to) {
        if (to == null || from == null || to == from || to.ordinal() < from.ordinal()) return null;
        if (to == Stage.DONE) return "First trade recorded.";
        if (to == Stage.WAIT_FILL) return "Offer synced. Check Positions.";
        if (to == Stage.PLACE_OFFER) return "GE is open. Place or view an offer.";
        return null;
    }

    public static String emptyFlips(Stage stage) {
        if (stage == Stage.OPEN_GE) return "No flips yet. Open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) return "No flips match. Place or view any GE offer.";
        if (stage == Stage.WAIT_FILL) return "No other flips right now. Your offer is on Positions.";
        return "No flips right now.";
    }

    public static String emptyPlan(Stage stage) {
        if (stage == Stage.OPEN_GE) return "No plan yet. Open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) return "Nothing to place. View an offer, or ease filters.";
        if (stage == Stage.WAIT_FILL) return "Nothing to place until a slot frees.";
        return "Nothing to place right now.";
    }

    public static String emptyPositions(Stage stage) {
        if (stage == Stage.OPEN_GE) return "No offers yet. Open the Grand Exchange.";
        if (stage == Stage.PLACE_OFFER) return "No offer yet. Buy the top Finder pick in the GE.";
        if (stage == Stage.WAIT_FILL) return "No open offers. Sell the fill to finish the flip.";
        return "No open offers.";
    }
}

